/**
 * `repr()` for Python's `float` and the `float(str)` constructor.
 *
 * Floats are plain JavaScript numbers throughout this port; the only thing that
 * needs porting is the textual shape, which differs from `Number.prototype
 * .toString()` in three ways: integral values keep a `.0`, the switch to
 * exponential notation happens at different magnitudes, and exponents are
 * zero-padded to two digits.
 */

import { PyConversionError } from './pyerrors.mjs';
import {
  isAsciiSpace,
  transformDecimalAndSpaceToAscii,
} from './pyunicode.mjs';

/**
 * Shortest decimal digit string that round-trips to `value`, plus the decimal
 * exponent of its leading digit.  `Number.prototype.toExponential()` with no
 * argument is specified to produce exactly those digits.
 */
function shortestDigits(value) {
  let text = value.toExponential();
  if (Number(text) !== value) {
    // Defensive: fall back to a widening search if a host ever deviates from
    // the shortest-round-trip requirement.
    for (let precision = 0; precision <= 17; precision += 1) {
      const candidate = value.toExponential(precision);
      if (Number(candidate) === value) {
        text = candidate;
        break;
      }
    }
  }
  const [mantissa, exponent] = text.split('e');
  const digits = mantissa.replace('.', '').replace('-', '');
  return { digits, exp10: Number(exponent) };
}

/**
 * `float.__repr__()` — CPython's `'r'` format code: shortest round-trip digits,
 * exponential notation when the decimal point lands at or before position -4 or
 * past position 16, and a mandatory trailing `.0` otherwise.
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || Object.is(value, -0);
  const magnitude = Math.abs(value);

  let digits = '0';
  let decpt = 1;
  if (magnitude !== 0) {
    const shortest = shortestDigits(magnitude);
    digits = shortest.digits;
    decpt = shortest.exp10 + 1;
  }

  let body;
  if (decpt <= -4 || decpt > 16) {
    const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits[0];
    const exponent = decpt - 1;
    const sign = exponent < 0 ? '-' : '+';
    body = `${mantissa}e${sign}${String(Math.abs(exponent)).padStart(2, '0')}`;
  } else if (decpt <= 0) {
    body = `0.${'0'.repeat(-decpt)}${digits}`;
  } else if (decpt >= digits.length) {
    body = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  } else {
    body = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
  }

  return negative ? `-${body}` : body;
}

/**
 * Strip the underscores PEP 515 allows, rejecting any that is not sandwiched
 * between two ASCII digits.  Mirrors
 * `_Py_string_to_number_with_underscores()`.
 */
function stripUnderscores(text) {
  if (!text.includes('_')) return text;
  const isDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '9';
  let out = '';
  let prev = '';
  for (const ch of text) {
    if (ch === '_') {
      if (!isDigit(prev)) return null;
    } else {
      if (prev === '_' && !isDigit(ch)) return null;
      out += ch;
    }
    prev = ch;
  }
  return prev === '_' ? null : out;
}

/** Trim the whitespace `Py_ISSPACE()` recognises from both ends. */
function stripAsciiSpace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isAsciiSpace(text[start])) start += 1;
  while (end > start && isAsciiSpace(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

const DECIMAL_FLOAT = /^(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][-+]?[0-9]+)?$/;

/**
 * `float(str)`.
 *
 * Accepts an optional sign followed by either a decimal literal or one of
 * `inf` / `infinity` / `nan` (any case), surrounded by optional whitespace,
 * with PEP 515 underscores permitted between digits.
 */
export function pyFloatFromString(text) {
  const folded = transformDecimalAndSpaceToAscii(text);
  const unscored = stripUnderscores(folded);
  if (unscored === null) throw new PyConversionError('could not convert string to float');

  let body = stripAsciiSpace(unscored);
  let sign = 1;
  if (body.startsWith('+')) {
    body = body.slice(1);
  } else if (body.startsWith('-')) {
    sign = -1;
    body = body.slice(1);
  }

  const lowered = body.toLowerCase();
  if (lowered === 'inf' || lowered === 'infinity') return sign * Infinity;
  if (lowered === 'nan') return NaN;

  if (!DECIMAL_FLOAT.test(body)) {
    throw new PyConversionError('could not convert string to float');
  }
  return sign * Number(body);
}

/**
 * The slices of CPython's Unicode database that the numeric constructors and
 * `repr()` depend on.
 *
 * Everything here is derived from observable behaviour: `int()`/`float()`
 * accept non-ASCII decimal digits and non-ASCII whitespace because
 * `_PyUnicode_TransformDecimalAndSpaceToASCII()` folds them down before the
 * ASCII parser ever runs, and `repr()` escapes anything that is not
 * "printable" in Python's sense.
 */

/**
 * Code points >= 127 that `Py_UNICODE_ISSPACE()` reports as whitespace.
 *
 * Note that this deliberately excludes the ASCII range: the decimal/space fold
 * only rewrites characters above 126, which is why `int('\x1c42')` fails even
 * though `'\x1c'.isspace()` is true — the ASCII parser's own notion of
 * whitespace (`Py_ISSPACE`) stops at CR.
 */
const NON_ASCII_SPACES = new Set([
  0x0085, // NEXT LINE
  0x00a0, // NO-BREAK SPACE
  0x1680, // OGHAM SPACE MARK
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
]);

/** True for the characters `Py_ISSPACE()` recognises: `\t\n\v\f\r` and space. */
export function isAsciiSpace(ch) {
  return ch === ' ' || (ch >= '\t' && ch <= '\r');
}

/** True for code points >= 127 that Python treats as whitespace. */
export function isNonAsciiSpace(codePoint) {
  return NON_ASCII_SPACES.has(codePoint);
}

const ND = /\p{Nd}/u;

/**
 * `Py_UNICODE_TODECIMAL()` — the decimal value of a code point, or -1.
 *
 * Decimal digits always appear in aligned runs of ten, so walking backwards
 * until the category stops matching yields the offset from that run's zero.
 */
export function decimalValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  if (!ND.test(String.fromCodePoint(codePoint))) return -1;
  let offset = 0;
  while (offset < 9 && ND.test(String.fromCodePoint(codePoint - offset - 1))) offset += 1;
  return offset;
}

/**
 * Port of `_PyUnicode_TransformDecimalAndSpaceToASCII()`.
 *
 * Characters below 127 pass through untouched; above that, whitespace becomes
 * a plain space, decimal digits become their ASCII counterpart, and anything
 * else becomes `'?'` so the subsequent parse is guaranteed to fail.
 */
export function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 127) {
      out += ch;
    } else if (isNonAsciiSpace(cp)) {
      out += ' ';
    } else {
      const digit = decimalValue(cp);
      out += digit < 0 ? '?' : String(digit);
    }
  }
  return out;
}

const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/**
 * `Py_UNICODE_ISPRINTABLE()` — false for the separator and "other" categories,
 * with U+0020 carved out as the one printable space.
 */
export function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

/**
 * Compare two strings the way CPython's `sorted()` does: by code point.
 *
 * JavaScript's `<` compares UTF-16 code units, which disagrees with Python for
 * astral characters (they sort below U+E000 instead of above it).
 */
export function codePointCompare(a, b) {
  const left = Array.from(a);
  const right = Array.from(b);
  const shared = Math.min(left.length, right.length);
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0);
    const y = right[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}
